  array['agencies_select_all', 'organizations_select_member', 'organizations_update_manager', 'org_logos_select_member', 'members_select_same_org', 'members_insert_manager', 'members_update_self_or_manager', 'members_delete_manager', 'subscriptions_select_member', 'subscription_agencies_select_member', 'entitlements_select_member', 'reports_select_researcher', 'reports_insert_researcher', 'reports_update_researcher', 'report_tags_select_researcher', 'report_files_select_entitled', 'report_files_insert_researcher', 'awarded_contracts_select_subscriber', 'contacts_select_researcher', 'contacts_update_researcher', 'crm_opportunities_select_member', 'crm_opportunities_insert_member', 'crm_opportunities_update_member', 'crm_opportunities_delete_manager', 'crm_opportunity_reports_member', 'crm_notes_select_member', 'crm_notes_insert_member', 'crm_notes_update_author', 'crm_notes_delete_author_or_manager', 'crm_tasks_select_member', 'crm_tasks_insert_member', 'crm_tasks_update_member', 'crm_tasks_delete_manager', 'researchers_select_researcher']::text[],
  'policies in the database == policies declared in privacy-rules.yaml'
);
